import { UseRefElementParameters, UseRefElementReturnType, useRefElement } from "../dom-helpers/use-ref-element.js";
import { OnPassiveStateChange, returnNull, runImmediately, useEnsureStability, usePassiveState } from "../preact-extensions/use-passive-state.js";
import { getDocument, getWindow } from "../util/get-window.js";
import { JSX, TagToElement, useCallback, useEffect, useRef } from "../util/lib.js";
import { useMonitoring } from "../util/use-call-count.js";

export interface UseElementSizeParametersSelf {
    /**
     * Called any time the browser detects a size change
     * on the element. Does not need to be stable, so you
     * can pass an anonymous function that only sets the
     * values you use if you'd like.
     * 
     * @stable
     */
    onSizeChange(sizeInfo: ElementSize, prevSize: ElementSize | undefined, entries: ResizeObserverEntry[] | UIEvent): void;

    /**
     * Passed as an argument to the created ResizeObserver.
     * 
     * @see https://developer.mozilla.org/en-US/docs/Web/API/ResizeObserver/observe#parameters
     * 
     * @stable 
     */
    getObserveBox: null | (() => ResizeObserverOptions["box"]);
}


export interface UseElementSizeParameters<Tag extends keyof JSX.IntrinsicElements> extends UseRefElementParameters<Tag> {
    elementSizeParameters: UseElementSizeParametersSelf;
}

export interface ElementSize {
    clientWidth: number;
    scrollWidth: number;
    offsetWidth: number | undefined;
    clientHeight: number;
    scrollHeight: number;
    offsetHeight: number | undefined;
    clientLeft: number;
    scrollLeft: number;
    offsetLeft: number | undefined;
    clientTop: number;
    scrollTop: number;
    offsetTop: number | undefined;
}

export interface UseElementSizeReturnTypeSelf {
    /** @stable */
    getSize(): ElementSize | null;
}


export interface UseElementSizeReturnType<Tag extends keyof JSX.IntrinsicElements> extends UseRefElementReturnType<Tag> {
    elementSizeReturn: UseElementSizeReturnTypeSelf;
}

/**
 * Measures an element, allowing you to react to its changes in size.
 * 
 * @compositeParams
 */
export function useElementSize<Tag extends keyof JSX.IntrinsicElements>({ elementSizeParameters: { getObserveBox, onSizeChange }, refElementParameters }: UseElementSizeParameters<Tag>): UseElementSizeReturnType<Tag> {
    return useMonitoring(function useElementSize(): UseElementSizeReturnType<Tag> {
        const { onElementChange, onMount, onUnmount } = (refElementParameters || {})

        useEnsureStability("useElementSize", getObserveBox, onSizeChange, onElementChange, onMount, onUnmount);

        const [getSize, setSize] = usePassiveState<ElementSize | null, UIEvent | ResizeObserverEntry[]>(onSizeChange as OnPassiveStateChange<ElementSize | null, UIEvent | ResizeObserverEntry[]>, returnNull, { debounceRendering: runImmediately, skipMountInitialization: true });

        const currentObserveBox = useRef<ResizeObserverBoxOptions | undefined>(undefined);

        const needANewObserver = useCallback((element: TagToElement<Tag> | null, observeBox: ResizeObserverBoxOptions | undefined) => {
            if (element) {
                const document = getDocument(element);
                const window = getWindow(element);

                const handleUpdate = (entries: ResizeObserverEntry[] | UIEvent) => {
                    if (element.isConnected) {
                        const { clientWidth, scrollWidth, offsetWidth, clientHeight, scrollHeight, offsetHeight, clientLeft, scrollLeft, offsetLeft, clientTop, scrollTop, offsetTop } = (element as Element & Partial<HTMLElement>);
                        setSize({ clientWidth, scrollWidth, offsetWidth, clientHeight, scrollHeight, offsetHeight, clientLeft, scrollLeft, offsetLeft, clientTop, scrollTop, offsetTop }, entries);
                    }
                }


                if (window && ("ResizeObserver" in window)) {
                    const observer = new ResizeObserver((entries) => { handleUpdate(entries); });

                    observer.observe(element, { box: observeBox });

                    return () => observer.disconnect();
                }
                else {
                    document?.addEventListener("resize", handleUpdate, { passive: true });
                    return () => document?.removeEventListener("resize", handleUpdate);
                }
            }
        }, [])

        const { refElementReturn, ...rest } = useRefElement<Tag>({
            refElementParameters: {
                onElementChange: useCallback((e: TagToElement<Tag> | null, p: TagToElement<Tag> | null | undefined, r?: never) => { needANewObserver(e, getObserveBox?.()); onElementChange?.(e, p, r); }, []),
                onMount,
                onUnmount
            }
        });

        const { getElement } = refElementReturn;

        useEffect(() => {
            if (getObserveBox) {
                if (currentObserveBox.current !== getObserveBox())
                    needANewObserver(getElement(), getObserveBox());
            }
        });

        return {
            elementSizeReturn: { getSize },
            refElementReturn,
            ...rest
        }

    });
}
